# generated by maixhub, tested on maixpy3 v0.4.8
# copy files to TF card and plug into board and power on
import sensor, image, lcd, time
import KPU as kpu
from machine import UART
import gc, sys
from fpioa_manager import fm

input_size = (224, 224)
labels = ['WhiteBall', 'YellowBall']
anchors = [1.62, 1.59, 0.87, 0.88, 2.53, 2.5, 2.09, 2.06, 1.19, 1.22]

focal_length = 350 # 焦距
known_object_size = 4  # 物体的实际宽度(cm)

#将串口资源注册到某个引脚上
#蓝牙
fm.register(24, fm.fpioa.UART1_TX, force = True)    #TX
fm.register(25, fm.fpioa.UART1_RX, force = True)    #RX

#stm32
fm.register(9, fm.fpioa.UART2_TX, force = True)     #TX
fm.register(10, fm.fpioa.UART2_RX, force = True)    #RX

#初始化串口
#蓝牙
uart_A = UART(UART.UART1, 9600, 8, 0, 1, timeout = 1000, read_buf_len = 4096)

#stm32
uart_B = UART(UART.UART2, 115200, 8, 0, 1, timeout = 1000, read_buf_len = 4096)

#发送数据给stm32
def sending_data(x, y):
    FH = bytearray([0x2C, 0x12, x, y, 0x5B])
    uart_B.write(FH);

# 计算距离
def calculate_distance(object_width_in_image):
    distance = (known_object_size * focal_length) / object_width_in_image
    return distance

def lcd_show_except(e):
    import uio
    err_str = uio.StringIO()
    sys.print_exception(e, err_str)
    err_str = err_str.getvalue()
    img = image.Image(size=input_size)
    img.draw_string(0, 10, err_str, scale=1, color=(0xff,0x00,0x00))
    lcd.display(img)

def main(anchors, labels = None, model_addr="/sd/m.kmodel", sensor_window=input_size, lcd_rotation=0, sensor_hmirror=False, sensor_vflip=False):
    sensor.reset(dual_buff = True);     #初始化摄像头 dual_buff打开可以提高帧率
    sensor.set_pixformat(sensor.RGB565)     #设置摄像头输出格式 默认为RGB565
    sensor.set_framesize(sensor.QVGA)   #设置分辨率 320*240
    sensor.set_windowing(sensor_window)
    sensor.set_hmirror(0)  #设置摄像头水平镜像
    sensor.set_vflip(1)    #设置摄像头垂直翻转
    sensor.run(1)   #启动摄像头
    sensor.skip_frames()    #刚启动时摄像头还不稳定 所以要跳过一些图像

    read_str = ""   #设置从蓝牙接受到的数据
    ball_id =  ""    #设置识别物体的ID（YelloBall, WhiteBall）

    lcd.init(type=1)    #设置屏幕显示类型为LCD_TYPE_ILI9486（224*224）
    lcd.rotation(lcd_rotation)
    lcd.clear(lcd.WHITE)    #将屏幕清空为白色

    if not labels:
        with open('labels.txt','r') as f:
            exec(f.read())
    if not labels:
        print("no labels.txt")
        img = image.Image(size=(320, 240))
        img.draw_string(90, 110, "no labels.txt", color=(255, 0, 0), scale=2)
        lcd.display(img)
        return 1
    try:
        img = image.Image("startup.jpg")
        lcd.display(img)
    except Exception:
        img = image.Image(size=(320, 240))
        img.draw_string(90, 110, "loading model...", color=(255, 255, 255), scale=2)
        lcd.display(img)

    try:
        task = None
        task = kpu.load(model_addr)  #将训练的模型导入到K210中
        kpu.init_yolo2(task, 0.5, 0.3, 5, anchors)  #初始化模型
        while(True):
            img = sensor.snapshot()
            t = time.ticks_ms()
            objects = kpu.run_yolo2(task, img)
            t = time.ticks_ms() - t

            read_date = uart_A.read()   #从蓝牙读取要跟踪的目标
            if read_date:
                read_str = read_date.decode('utf-8')

            if objects:
                for obj in objects:
                    pos = obj.rect()    #pos[0]左上角x pos[1]左上角y pos[2]矩形宽度 pos[3]矩形高度
                    img.draw_rectangle(pos)
                    ball_id = labels[obj.classid()]
                    object_width_in_image = min(pos[2], pos[3])   #物体在图像中的像素宽度
                    distance = calculate_distance(object_width_in_image)    #物体距离摄像头的距离
                    object_axisX_in_image = pos[0] + pos[2] / 2;    #发送给stm32的方位(x小于112为左，大于为右)
                    img.draw_string(pos[0], pos[1], "%s : %.2f" %(labels[obj.classid()], distance), scale=1, color=(255, 0, 0))
                    if read_str == labels[obj.classid()]:     #蓝牙发送数据与识别物体标签相匹配
                        sending_data(int(distance), int(object_axisX_in_image))   #数据为int类型 方便后续的判断
            if read_str != ball_id:  #目标不匹配时 停止追踪
                sending_data(0, 0)  #重置发送给stm32的距离和方向
            img.draw_string(0, 200, "t:%dms" %(t), scale=1, color=(255, 0, 0))
            lcd.display(img)
            time.sleep_ms(30)   #延时30ms 防止特殊变量被覆盖
    except Exception as e:
        raise e
    finally:
        if not task is None:
            kpu.deinit(task)

if __name__ == "__main__":
    try:
        # main(anchors = anchors, labels=labels, model_addr=0x300000, lcd_rotation=0)
        main(anchors = anchors, labels=labels, model_addr="/sd/model-203622.kmodel")
    except Exception as e:
        sys.print_exception(e)
        lcd_show_except(e)
    finally:
        gc.collect()
